from collections import defaultdict
from typing import List

def maximum_sum_of_balanced_subsequence(nums: List[int]) -> int:
    # nums[i_j] - nums[i_{j-1}] == i_j - i_{j-1}  <=>  nums[i] - i 在子序列中处处相同
    pos_sum = defaultdict(int)
    best_single = max(nums)
    for i, x in enumerate(nums):
        if x > 0:
            pos_sum[x - i] += x
    return max([best_single] + list(pos_sum.values()))
